export const BODY: string = "\n<p>تصویر سے میٹا ڈیٹا ہٹانا اس کی چھپی ہوئی معلومات مٹانا ہے: مقام، تاریخ، کیمرے کا نام اور سیٹنگز۔ یہ کام شیئر کرنے سے پہلے ضروری ہے، خاص طور پر نجی تصویروں کے لیے۔</p>\n<p>میٹا ڈیٹا ہٹانے سے تصویر خود نہیں بدلتی: رنگ، پکسلز اور تیزرفتاری ویسی ہی رہتی ہے۔ صرف فائل کے اندر لکھی معلومات ختم ہوتی ہے۔</p>\n<p>یہ رہنما بتاتا ہے کہ میٹا ڈیٹا کیوں ہٹائیں، دو طریقے کیا ہیں، بیچ میں کیسے صاف کریں، اور صاف شدہ فائل کی تصدیق کیسے کریں۔ صاف کرنے کے لیے <a href=\"/ur/tasveer-metadata-hatayein/\">میٹا ڈیٹا ہٹائیں</a> استعمال کریں۔</p>\n<h2 id=\"what-is-metadata-removal\">میٹا ڈیٹا ہٹانا کیا ہے؟</h2>\n<p>میٹا ڈیٹا ہٹانا فائل سے اضافی معلومات مٹانا ہے، بغیر تصویر کو چھوئے۔ EXIF، GPS اور کیمرے کی معلومات ختم ہو جاتی ہیں، مگر پکسلز وہی رہتے ہیں۔</p>\n<p>یہ کام اس لیے ضروری ہے کہ میٹا ڈیٹا آپ کا پتہ اور عادتیں بتا سکتا ہے۔ شیئر کی گئی تصویر کے ساتھ یہ معلومات ہر دیکھنے والے تک پہنچتی ہے۔</p>\n<p>میٹا ڈیٹا ہٹانا تصویر کو خراب نہیں کرتا۔ یہ صرف فائل کو ہلکا اور محفوظ بناتا ہے۔</p>\n<h2 id=\"why-remove-metadata\">شیئر کرنے سے پہلے میٹا ڈیٹا کیوں ہٹائیں؟</h2>\n<p>میٹا ڈیٹا میں GPS ہو سکتا ہے، جو آپ کے گھر کا پتہ بتاتا ہے۔ بچوں اور گھر کی تصویروں میں یہ سب سے بڑا خطرہ ہے۔</p>\n<p>میٹا ڈیٹا میں تاریخ اور کیمرے کی معلومات بھی ہوتی ہیں، جو آپ کی عادتیں بتا سکتی ہیں۔ شیئر کرنے سے پہلے اسے ہٹانا پرائیویسی کی حفاظت ہے۔</p>\n<p>کاروبار کے لیے بھی میٹا ڈیٹا ہٹانا ضروری ہے، کیونکہ مصنوعات کی تصویروں میں دفتر کا مقام ہو سکتا ہے۔</p>\n<h2 id=\"stripping-methods\">ہٹانے کے دو طریقے</h2>\n<p>پہلا طریقہ بغیر نقصان کے ہٹانا ہے: صرف میٹا ڈیٹا مٹایا جاتا ہے، پکسلز چھوئے نہیں جاتے۔ تصویر بالکل ویسی رہتی ہے، جیسی پہلے تھی۔</p>\n<p>دوسرا طریقہ دوبارہ بنانا ہے: تصویر کو نئے سرے سے لکھا جاتا ہے، جس سے میٹا ڈیٹا بھی ختم ہوتا ہے اور معیار بھی تھوڑا بدل سکتا ہے۔</p>\n<p>پہلا طریقہ بہتر ہے، کیونکہ وہ تصویر کو بالکل نہیں بدلتا۔ دوسرا طریقہ اس وقت استعمال کریں جب پہلا کام نہ کرے۔</p>\n<h2 id=\"lossless-vs-reencode\">بغیر نقصان ہٹانا بمقابلہ دوبارہ بنانا</h2>\n<p>بغیر نقصان ہٹانے میں صرف فائل کا ہیڈر بدلا جاتا ہے، پکسلز نہیں۔ تصویر کا معیار، رنگ اور سائز وہی رہتا ہے۔</p>\n<p>دوبارہ بنانے میں تصویر کو دوبارہ کمپریس کیا جاتا ہے، جس سے معیار تھوڑا گر سکتا ہے۔ لیکن یہ طریقہ ہر فارمیٹ پر کام کرتا ہے۔</p>\n<p>اہم تصویروں کے لیے بغیر نقصان والا طریقہ چنیں۔ عام تصویروں کے لیے دونوں چلتے ہیں۔</p>\n<h2 id=\"how-to-remove-metadata\">میٹا ڈیٹا کیسے ہٹائیں، قدم بہ قدم</h2>\n<p>تصویر ٹول میں ڈالیں، ہٹانے کا طریقہ چنیں اور صاف شدہ فائل ڈاؤن لوڈ کریں۔ پھر اسے ویور میں ڈال کر جانچیں کہ میٹا ڈیٹا ختم ہوا یا نہیں۔</p>\n<p>جانچ بہت اہم ہے، کیونکہ کچھ ٹول میٹا ڈیٹا کا صرف ایک حصہ ہٹاتے ہیں۔ دوبارہ جانچے بغیر شیئر کرنا خطرہ مول لینا ہے۔</p>\n<p>اگر میٹا ڈیٹا اب بھی نظر آئے تو دوسرا طریقہ آزمائیں۔ دوبارہ بنانے والا طریقہ اکثر باقی میٹا ڈیٹا بھی ہٹا دیتا ہے۔</p>\n<h2 id=\"batch-cleaning\">پورا بیچ ایک ساتھ صاف کرنا</h2>\n<p>بیچ میں درجنوں تصویریں ایک ساتھ صاف کی جا سکتی ہیں۔ پوری گیلری یا کیٹلاگ کے لیے یہ بہت وقت بچاتا ہے۔</p>\n<p>بیچ صاف کرنے سے پہلے ایک تصویر آزمائیں اور جانچیں۔ اگر وہ صاف ہو تو پوری بیچ صاف کریں۔</p>\n<p>بیچ کا نتیجہ ZIP میں ملتا ہے، جس میں نام وہی رہتے ہیں۔ ZIP کھولنے کے بعد چند تصویریں دوبارہ جانچیں۔</p>\n<h2 id=\"output-formats\">آؤٹ پٹ فارمیٹ اور معیار</h2>\n<p>صاف شدہ فائل اسی فارمیٹ میں ملتی ہے جس میں اصل تھی: JPG کی JPG اور PNG کی PNG۔ فارمیٹ نہیں بدلتا، صرف میٹا ڈیٹا ہٹتا ہے۔</p>\n<p>معیار بھی وہی رہتا ہے، اگر بغیر نقصان والا طریقہ استعمال ہو۔ دوبارہ بنانے والے طریقے میں معیار تھوڑا گر سکتا ہے۔</p>\n<p>اگر فارمیٹ بدلنا ہو تو صاف کرنے سے پہلے یا بعد میں کنورٹر استعمال کریں۔ دونوں کام الگ الگ کریں۔</p>\n<h2 id=\"verifying-clean\">صاف شدہ فائل کی تصدیق</h2>\n<p>تصدیق کے لیے صاف شدہ فائل کو <a href=\"/ur/tasveer-metadata-dekhein/\">میٹا ڈیٹا ویور</a> میں ڈالیں۔ صاف فائل میں GPS اور کیمرے کی معلومات نہیں ہونی چاہییں۔</p>\n<p>صرف بنیادی معلومات، جیسے ابعاد اور فارمیٹ، رہنی چاہییں۔ اگر GPS اب بھی نظر آئے تو فائل صاف نہیں ہوئی۔</p>\n<p>تصدیق کے بغیر شیئر نہ کریں۔ چند سیکنڈ کی جانچ بڑے خطرے سے بچاتی ہے۔</p>\n<h2 id=\"metadata-on-mobile\">موبائل پر میٹا ڈیٹا ہٹانا</h2>\n<p>ٹول براؤزر میں چلتا ہے، اس لیے موبائل پر بھی کام کرتا ہے۔ گیلری سے تصویر منتخب کریں، صاف کریں اور نتیجہ ڈاؤن لوڈ کریں۔</p>\n<p>موبائل پر صاف کرنے سے پہلے اصل تصویر کا بیک اپ لیں، کیونکہ صاف شدہ فائل سے میٹا ڈیٹا واپس نہیں ملتا۔</p>\n<p>فون کی سیٹنگ میں کیمرے کے لیے مقام بند کر دیں، تاکہ نئی تصویروں میں GPS نہ لکھا جائے۔</p>\n<h2 id=\"what-removal-does-not-do\">ہٹانا کیا نہیں کرتا</h2>\n<p>میٹا ڈیٹا ہٹانا تصویر میں نظر آنے والی معلومات نہیں ہٹاتا: پس منظر میں گھر کا نمبر یا سڑک کا نام تصویر میں ہی رہتا ہے۔</p>\n<p>ہٹانا تصویر کی سمت بھی بدل سکتا ہے، اگر سمت کا میٹا ڈیٹا ہٹ جائے۔ صاف کرنے کے بعد تصویر کو دیکھ کر سمت جانچیں۔</p>\n<p>ہٹانا تصویر کو محفوظ نہیں بناتا، اگر تصویر خود نجی معلومات دکھاتی ہو۔ تصویر کا ہر حصہ جانچیں، نہ صرف میٹا ڈیٹا۔</p>\n<h2 id=\"cleaning-by-source\">مختلف ذرائع کی تصویریں صاف کرنا</h2>\n<p>فون کی تصویروں میں سب سے زیادہ میٹا ڈیٹا ہوتا ہے، کیونکہ فون مقام اور کیمرے کی معلومات لکھتا ہے۔ انہیں ضرور صاف کریں۔</p>\n<p>ڈی ایس ایل آر کی تصویروں میں بھی بہت میٹا ڈیٹا ہوتا ہے، مگر GPS کم ہوتا ہے۔ اسکرین شاٹ میں میٹا ڈیٹا کم ہوتا ہے۔</p>\n<p>ڈاؤن لوڈ شدہ تصویروں میں بھی میٹا ڈیٹا ہو سکتا ہے۔ کسی بھی تصویر کو شیئر کرنے سے پہلے جانچیں، چاہے وہ کہیں سے آئی ہو۔</p>\n<h2 id=\"file-size-after-stripping\">ہٹانے کے بعد فائل کا سائز</h2>\n<p>میٹا ڈیٹا ہٹانے سے فائل تھوڑی ہلکی ہو جاتی ہے، کیونکہ اضافی معلومات ختم ہو جاتی ہیں۔ بچت عام طور پر چند کلو بائٹ ہوتی ہے۔</p>\n<p>لیکن فائل ہلکی کرنا ہٹانے کا مقصد نہیں، پرائیویسی مقصد ہے۔ بچت چھوٹی ہے، مگر حفاظت بڑی ہے۔</p>\n<p>اگر فائل بہت ہلکی ہو گئی ہو تو جانچیں کہ تصویر خراب تو نہیں ہوئی۔ بغیر نقصان والے طریقے میں تصویر ویسی ہی رہتی ہے۔</p>\n<h2 id=\"metadata-removal-summary\">مختصر خلاصہ</h2>\n<p>میٹا ڈیٹا ہٹانا شیئر کرنے سے پہلے کا ضروری قدم ہے: جانچیں، صاف کریں اور دوبارہ جانچیں۔ یہ عادت آپ کی پرائیویسی بچاتی ہے۔</p>\n<p>اصل فائل محفوظ رکھیں، کیونکہ صاف شدہ فائل سے میٹا ڈیٹا واپس نہیں ملتا۔ عملی مراحل <a href=\"/ur/blog/tasveer-se-metadata-kaise-hatayein/\">تصویر سے میٹا ڈیٹا کیسے ہٹائیں</a> میں اور جانچنے کا طریقہ <a href=\"/ur/tasveer-metadata-dekhein/\">میٹا ڈیٹا ویور</a> میں دیکھیں۔ سائز بدلنا ہو تو <a href=\"/ur/tasveer-resize-karein/\">امیج ری سائزر</a> استعمال کریں۔</p>\n";

